router.get("/orders/:id", requireSignedIn, async (req, res) => {
  const id = Number(req.params.id);
  if (!Number.isInteger(id) || id <= 0) return res.status(400).send("Invalid order id");
  const [rows] = await db.query("SELECT * FROM orders WHERE id = ?", [id]);
  const order = rows[0];
  if (!order || order.guestId !== req.user.guestId || !req.user.permissions.includes("orders:read")) return res.status(403).end();
  logger.info("order_lookup", { orderId: hash(id), outcome: "requested" });
  res.json(order);
});

